/bin/bash -lc "python3 - <<'PY'
from pathlib import Path
import ast,hashlib,json,subprocess
p=Path('proposal.json'); x=json.loads(p.read_text())
for contrast in x['study']['contrasts']:
    contrast['held_fixed']=[s.replace('256-bin salt0 hash and full/native arithmetic; no group merging','256-bin salt0 hash and native arithmetic; no group merging') for s in contrast['held_fixed']]
p.write_text(json.dumps(x,indent=2)+'\\n')
r=json.loads(subprocess.check_output(['python3','/workspace/tools.py','resolve','run://r-001'],text=True))
def validate(value,schema,path='"'$'"'):
    types={'object':dict,'array':list,'string':str,'boolean':bool,'number':(float,int),'integer':int}
    if 'type' in schema: assert isinstance(value,types[schema['type']]),(path,'type')
    if 'enum' in schema: assert value in schema['enum'],(path,'enum')
    if 'const' in schema: assert value==schema['const'],(path,'const')
    if 'minLength' in schema: assert len(value)>=schema['minLength'],(path,'length')
    if 'minItems' in schema: assert len(value)>=schema['minItems'],(path,'items')
    if isinstance(value,dict):
        for k in schema.get('required',[]): assert k in value,(path,'missing',k)
        props=schema.get('properties',{})
        if schema.get('additionalProperties') is False: assert not set(value)-set(props),(path,'extra')
        for k,v in value.items():
            if k in props: validate(v,props[k],path+'.'+k)
    if isinstance(value,list) and 'items' in schema:
        for i,v in enumerate(value): validate(v,schema['items'],path+f'[{i}]')
validate(x['study'],r['study_schema'])
assert x['study']['protocol_ref']==r['required_study_protocol_ref']
allowed=set(r['context']['allowed_observation_ids'])
assert x['parent_trial'] in allowed
for e in x['study']['evidence_refs']:
    assert e in allowed or e in {'paper:din','paper:dmr','taac2026-organizer-overview'}, e
assert 1<=len(x['variants'])<=4
assert len({v['name'] for v in x['variants']})==len(x['variants'])
assert len({v['file'] for v in x['variants']})==len(x['variants'])
assert any(v['role']=='candidate' for v in x['variants'])
old_tree=ast.parse(Path('history_g2_r0022_support_shared.py').read_text())
def model(t): return next(n for n in t.body if isinstance(n,ast.ClassDef) and n.name=='Model')
def methods(t): return {n.name:ast.dump(n,include_attributes=False) for n in model(t).body if isinstance(n,ast.FunctionDef)}
old=methods(old_tree); models=[]
for v in x['variants']:
    assert v['role'] in ('candidate','control')
    assert Path(v['file']).name==v['file'] and v['file'].endswith('.py')
    src=Path(v['file']).read_text(); tree=ast.parse(src); compile(src,v['file'],'exec')
    cfg=next(ast.literal_eval(n.value) for n in tree.body if isinstance(n,ast.Assign) and any(isinstance(t,ast.Name) and t.id=='CONFIG' for t in n.targets))
    assert cfg==v['config']
    assert cfg['constant_arithmetic']=='native' and cfg['share_partition'] is True
    assert hashlib.sha256(src.encode()).hexdigest() in v['note']
    now=methods(tree)
    assert [k for k in old if now[k]"'!=old[k]]==['"'_execution_parts','diagnostics']
    models.append(ast.dump(model(tree),include_attributes=False))
assert len(set(models))==1
assert {a['knowledge_id'] for a in x['knowledge_assessments']}=={'taac2026-academic-1-craft','taac2026-academic-2-unidac','taac2026-academic-3-unitokenformer','taac2026-industry-1-queryformer','taac2026-industry-2-unidot'}
assert all(a['decision'] in {'used','considered','rejected','unresolved'} for a in x['knowledge_assessments'])
assert hashlib.sha256(Path('baseline_reference.py').read_bytes()).hexdigest()=='ee10868f589c077b19f57a1fb07702c947c56e970994cdc537ef83ea2b8bc943'
assert 12*r['context']['protocol']['trial_cap_seconds']<r['context']['remaining_seconds']
print('PASS: supplied study-schema subset validator covers all schema keywords in use; protocol/evidence/parent/registrations/config/source hashes/unchanged25methods/5card assessments/12unit reserve match.')
print('PASS:4standalone modules compile without Torch import; same Model AST; baseline untouched.')
print('Pending authorized host: import, forward/backward,53finite diagnostics, numerical equality, validation metrics, timing/memory, paired-seed assessment.')
print('Files:',[(v['name'],v['file'],v['role']) for v in x['variants']])
PY"

